void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // 1. Normalize coordinates to 0.0 - 1.0
    vec2 uv = fragCoord / iResolution.xy;

    // 2. Define the triangle mask
    float mask = 0.0;

    // We keep the peak at Y = 0.8 (Top) and base at Y = 0.2 (Bottom)
    if (uv.y > 0.2 && uv.y < 0.8) {
        // As Y increases (moves toward 0.8), the width decreases
        float width = (0.8 - uv.y) * 0.6; 
        if (abs(uv.x - 0.5) < width) {
            mask = 1.0;
        }
    }

    // 3. Output Colors (Matching your p5.js fill: 255, 255, 100)
    vec3 yellow = vec3(1.0, 1.0, 0.39); // Normalized (255/255, 255/255, 100/255)
    vec3 backgroundColor = vec3(0.0);    // Black (matches a cleared canvas)

    vec3 finalColor = mix(backgroundColor, yellow, mask);

    fragColor = vec4(finalColor, 1.0);
}

