function render({t}) {
  glsl({
    t,
    // We use a single quad (Mesh: [1, 1]) to act as a canvas
    Mesh: [1, 1], 
    // VP: Maps the mesh to fill the screen
    VP: `XY, 0, 1`, 
    // FP: The fragment shader logic
    FP: `
      vec2 uv = UV; // UV coordinates from 0.0 to 1.0
      float mask = 0.0;

      // Define triangle logic: peak at Y=0.8, base at Y=0.2
      if (uv.y > 0.2 && uv.y < 0.8) {
          float width = (0.8 - uv.y) * 0.6;
          if (abs(uv.x - 0.5) < width) {
              mask = 1.0;
          }
      }

      // Color: Yellow (1.0, 1.0, 0.4) on Black background
      FOut = vec4(vec3(1.0, 1.0, 0.4) * mask, 1.0);
    `
  })
}

