const { Scene, PerspectiveCamera, PlaneGeometry, ShaderMaterial, Mesh, Vector2 } = THREE

const scene = new Scene()
const camera = new PerspectiveCamera(75, width / height, 0.1, 1000)
camera.position.z = 1.5

// 1. Create a Plane instead of a Cube
const geometry = new PlaneGeometry(1, 1)

// 2. Use a ShaderMaterial to draw the triangle logic
const material = new ShaderMaterial({
  uniforms: {
    iResolution: { value: new Vector2(width, height) }
  },
  vertexShader: `
    varying vec2 vUv;
    void main() {
      vUv = uv; // Pass the plane's UVs to the fragment shader
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    varying vec2 vUv;
    void main() {
      vec2 uv = vUv;
      float mask = 0.0;

      // Triangle Logic (Peak at Y=0.8, Base at Y=0.2)
      if (uv.y > 0.2 && uv.y < 0.8) {
          float width = (0.8 - uv.y) * 0.6;
          if (abs(uv.x - 0.5) < width) {
              mask = 1.0;
          }
      }

      // Output Yellow (1.0, 1.0, 0.4)
      gl_FragColor = vec4(vec3(1.0, 1.0, 0.4) * mask, 1.0);
    }
  `
})

const plane = new Mesh(geometry, material)
scene.add(plane)

function draw() {
  // No rotation needed for the test, but you can add it if you like
  renderer.render(scene, camera)
}

